-- Organizations II: new references include tenant ownership. Receipts deliberately
-- do not reference invitations: deletion must preserve committed acceptance replay.
ALTER TABLE organizations ADD COLUMN is_app_entitlement_active BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE organization_connections ADD COLUMN is_enabled BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE organization_connections ADD COLUMN connection_name LONGTEXT NOT NULL;
ALTER TABLE organization_connections ADD COLUMN organization_access_level VARCHAR(16) NOT NULL DEFAULT 'none';
ALTER TABLE organization_connections ADD COLUMN organization_member_access_level VARCHAR(16) NOT NULL DEFAULT 'limited';
UPDATE organization_connections SET connection_name=(SELECT name FROM connections WHERE connections.tenant_id=organization_connections.tenant_id AND connections.id=organization_connections.connection_id) WHERE EXISTS (SELECT 1 FROM connections WHERE connections.tenant_id=organization_connections.tenant_id AND connections.id=organization_connections.connection_id);
ALTER TABLE client_grants ADD COLUMN organization_usage VARCHAR(16) NOT NULL DEFAULT 'deny';
ALTER TABLE client_grants ADD COLUMN allow_any_organization BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE organization_invitations (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, id VARBINARY(255) NOT NULL, client_id VARCHAR(255) NOT NULL, connection_id VARCHAR(255) NULL, ticket_hash VARBINARY(255) NOT NULL, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, payload LONGTEXT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE (tenant_id,ticket_hash), FOREIGN KEY (tenant_id,organization_id) REFERENCES organizations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,client_id) REFERENCES clients(tenant_id,client_id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,connection_id) REFERENCES connections(tenant_id,id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX organization_invitations_active ON organization_invitations (tenant_id,organization_id,expires_at,created_at,id);
CREATE TABLE organization_invitation_roles (tenant_id VARCHAR(64) NOT NULL, invitation_id VARBINARY(255) NOT NULL, role_id VARBINARY(255) NOT NULL, PRIMARY KEY (tenant_id,invitation_id,role_id), FOREIGN KEY (tenant_id,invitation_id) REFERENCES organization_invitations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,role_id) REFERENCES rbac_roles(tenant_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE organization_invitation_receipts (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, invitation_id VARBINARY(255) NOT NULL, transaction_id VARBINARY(255) NOT NULL, user_id VARBINARY(1280) NOT NULL, accepted_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,transaction_id), UNIQUE (tenant_id,invitation_id), FOREIGN KEY (tenant_id,organization_id) REFERENCES organizations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,user_id) REFERENCES users(tenant_id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE organization_clients (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, client_id VARCHAR(255) NOT NULL, use_for_member_access BOOLEAN NOT NULL, PRIMARY KEY (tenant_id,organization_id,client_id), FOREIGN KEY (tenant_id,organization_id) REFERENCES organizations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,client_id) REFERENCES clients(tenant_id,client_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE organization_client_grants (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, grant_id VARCHAR(255) NOT NULL, PRIMARY KEY (tenant_id,organization_id,grant_id), FOREIGN KEY (tenant_id,organization_id) REFERENCES organizations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY (tenant_id,grant_id) REFERENCES client_grants(tenant_id,id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX organization_client_grants_reverse ON organization_client_grants (tenant_id,grant_id,organization_id);
CREATE TABLE organization_discovery_domains (tenant_id VARCHAR(64) NOT NULL, organization_id VARBINARY(255) NOT NULL, id VARBINARY(255) NOT NULL, domain VARBINARY(255) NOT NULL, status VARCHAR(255) NOT NULL, use_for_organization_discovery BOOLEAN NOT NULL, payload LONGTEXT NOT NULL, PRIMARY KEY (tenant_id,organization_id,id), UNIQUE (tenant_id,organization_id,domain), FOREIGN KEY (tenant_id,organization_id) REFERENCES organizations(tenant_id,id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX organization_discovery_domains_lookup ON organization_discovery_domains (tenant_id,domain,status,use_for_organization_discovery,organization_id);
ALTER TABLE password_reset_tickets ADD COLUMN organization_id VARBINARY(255) NOT NULL DEFAULT '';
